224	/**
225	 * A claim's status. It starts as DRAFT, is opened (OPEN) and then settled (SETTLED); a DRAFT,
226	 * OPEN or PENDING claim can be voided (VOID). A clerk's settling above the clerk limit makes it
227	 * PENDING instead, until a steward approves it (SETTLED) or rejects it (OPEN again). SETTLED and
228	 * VOID are final.
229	 */
230	public enum ClaimStatus {
231	    DRAFT, OPEN, PENDING, SETTLED, VOID;
232	
233	    /**
234	     * Whether a claim in this status may move to {@code next} by opening, settling or voiding it; a
235	     * PENDING claim leaves for SETTLED or OPEN only by a steward's approval or rejection.
236	     */
237	    public boolean canBecome(ClaimStatus next) {
238	        return switch (next) {
239	            case OPEN -> this == DRAFT;
240	            case PENDING, SETTLED -> this == OPEN;
241	            case VOID -> this == DRAFT || this == OPEN || this == PENDING;
242	            case DRAFT -> false;
243	        };
244	    }
245	
246	    /** Whether a claim in this status is open: OPEN, or PENDING, which is handled like it. */
247	    public boolean isOpen() {
248	        return this == OPEN || this == PENDING;
249	    }
250	
251	    /** Whether a claim in this status counts toward what is claimed and due. */
252	    public boolean counts() {
253	        return isOpen() || this == SETTLED;
254	    }
255	}
