264	/**
265	 * How a claim's live figures (the rate step and the late charge) round to cents: half up when the
266	 * claim is dated before the sheet's policy date (none: the sheet's today), else half to even. A
267	 * correction rounds by the date of the claim it corrects, not its own.
268	 */
269	public final class Rounding {
270	
271	    private Rounding() {}
272	
273	    /** The date a claim rounds by: a correction's corrected claim's date (from {@code datesByNumber}), else its own. */
274	    public static LocalDate basisOf(Claim claim, Map<String, LocalDate> datesByNumber) {
275	        if (claim.getCorrects() != null) {
276	            LocalDate corrected = datesByNumber.get(claim.getCorrects());
277	            if (corrected != null) return corrected;
278	        }
279	        return claim.getDate();
280	    }
281	
282	    /** The rounding of a claim rounding by the given date. */
283	    public static RoundingMode of(LocalDate basis, LocalDate policyDate, LocalDate today) {
284	        LocalDate policy = policyDate != null ? policyDate : today;
285	        return policy != null && basis.isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
286	    }
287	
288	    /** The dates of the numbered claims, by number. */
289	    public static Map<String, LocalDate> datesByNumber(List<Claim> claims) {
290	        Map<String, LocalDate> dates = new HashMap<>();
291	        for (Claim c : claims) {
292	            if (c.getNumber() != null) dates.put(c.getNumber(), c.getDate());
293	        }
294	        return dates;
295	    }
296	}
