300	import java.math.RoundingMode;
301	import java.time.LocalDate;
302	import java.time.temporal.ChronoUnit;
303	
304	/**
305	 * The late charge on an overdue claim: the sheet's late percent of its figure (the due bound by a
306	 * statement, else its floored live due) for every full 30 days past its due-by, rounded to cents like
307	 * its due ({@link Rounding}). A correction has none. It is never bound by a statement; settling freezes it into the settled due.
308	 */
309	public final class LateCharge {
310	
311	    /** The days in each step of the charge. */
312	    private static final int STEP_DAYS = 30;
313	
314	    private LateCharge() {}
315	
316	    /** Overdue: OPEN (or PENDING), not deferred, with its due-by (fixed when it was added) before the sheet's today. */
317	    public static boolean isOverdue(Claim claim, LocalDate today) {
318	        return claim.getStatus().isOpen() && today != null && claim.getDueBy().isBefore(today)
319	                && !claim.isDeferredOn(today);
320	    }
321	
322	    /** The charge on the claim with the given figure (null: none) as of today; zero when not overdue or a correction. */
323	    public static BigDecimal of(Claim claim, BigDecimal figure, LocalDate today, BigDecimal latePct,
324	            RoundingMode rounding) {
325	        BigDecimal zero = BigDecimal.ZERO.setScale(2);
326	        if (figure == null || claim.isCorrection() || !isOverdue(claim, today)) return zero;
327	        long steps = ChronoUnit.DAYS.between(claim.getDueBy(), today) / STEP_DAYS;
328	        return figure.multiply(latePct).multiply(BigDecimal.valueOf(steps)).movePointLeft(2)
329	                .setScale(2, rounding);
330	    }
331	
332	    /**
333	     * The figure with the charge it would have on top were the claim open now, whatever its status; null
334	     * when the figure is.
335	     */
336	    public static BigDecimal withChargeAsOpen(Claim claim, BigDecimal figure, LocalDate today, BigDecimal latePct,
337	            RoundingMode rounding) {
338	        if (figure == null || claim.isCorrection() || today == null || !claim.getDueBy().isBefore(today)) {
339	            return figure;
340	        }
341	        long steps = ChronoUnit.DAYS.between(claim.getDueBy(), today) / STEP_DAYS;
342	        return figure.add(figure.multiply(latePct).multiply(BigDecimal.valueOf(steps)).movePointLeft(2)
343	                .setScale(2, rounding));
344	    }
345	
346	    /** The figure with its charge added on top; null when the figure is. */
347	    public static BigDecimal withCharge(Claim claim, BigDecimal figure, LocalDate today, BigDecimal latePct,
348	            RoundingMode rounding) {
349	        return figure == null ? null : figure.add(of(claim, figure, today, latePct, rounding));
350	    }
351	}
