369	import net.officefloor.hq.app.setting.Role;
370	import net.officefloor.hq.app.setting.SettingService;
371	import net.officefloor.hq.app.sheet.Sheet;
372	import net.officefloor.hq.app.sheet.SheetService;
373	import org.springframework.stereotype.Service;
374	import org.springframework.transaction.annotation.Transactional;
375	
376	/**
377	 * The claims on a sheet: listed newest first, added to a person and edited one at a time. A claim
378	 * given no date takes the sheet's today. Its due-by is fixed when it is added: its date plus the terms
379	 * in force on that date of its person's grade then (else the sheet's terms in force on it); it does not
380	 * move when its date or the terms change later. A claim is added as DRAFT and moves through its statuses
381	 * as {@link ClaimStatus} allows; a change it does not allow is refused. Opening a claim gives it
382	 * the sheet's next number (or, while the sheet numbers by period, the next within its period), which it
383	 * keeps when voided and is never given again. Only a DRAFT claim
384	 * can be edited; an OPEN one is changed by voiding it and adding a new one. Settling it
385	 * fixes its due at its figure (the due bound by a statement, else its person's grade rate of the
386	 * moment on the claim's date) with its late charge of the moment frozen in; with no figure it
387	 * stays live. A steward can re-settle a SETTLED claim at the figure it would have today as an open claim
388	 * bound by no statement. The user who opened a claim cannot settle it, and a clerk cannot settle one whose
389	 * due is above the sheet's clerk limit (a steward can). No claim dated inside a closed period can
390	 * be added, edited (to or from such a date), opened, settled, re-settled or voided. No claim can be added
391	 * or edited to a date after its person's retirement date. A claim with a negative amount is a
392	 * correction: it must name, by number, a SETTLED claim of the same person; only a correction may name one.
393	 */
394	@Service
395	public class ClaimService {
396	
397	    private final ClaimRepository claims;
398	    private final PersonRepository people;
399	    private final RateService rates;
400	    private final SheetService sheets;
401	    private final RollupService rollup;
402	    private final PeriodRepository periods;
403	    private final SettingService settings;
404	    private final Audit audit;
405	
406	    public ClaimService(ClaimRepository claims, PersonRepository people, RateService rates, SheetService sheets,
407	            RollupService rollup, PeriodRepository periods, SettingService settings, Audit audit) {
408	        this.settings = settings;
409	        this.periods = periods;
410	        this.claims = claims;
411	        this.people = people;
412	        this.rates = rates;
413	        this.sheets = sheets;
414	        this.rollup = rollup;
415	        this.audit = audit;
416	    }
417	
418	    @Transactional(readOnly = true)
419	    public List<Claim> list(String sheetId) {
420	        return claims.findBySheetIdOrderByListedDesc(sheetId);
421	    }
422	
423	    @Transactional
424	    public Claim add(String sheetId, String user, Long personId, BigDecimal amount, LocalDate date, String note,
425	            String corrects) {
426	        // The snapshot locks the sheet first, so the person is read as retired by any retirement before.
427	        RollupService.Snapshot before = rollup.snapshot(sheetId);
428	        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
429	        LocalDate on = dateOrToday(sheetId, date);
430	        refuseIfClosed(sheetId, on);
431	        if (!person.mayClaimOn(on)) throw new PersonRetiredException();
432	        refuseUnlessCorrects(sheetId, personId, amount, corrects);
433	        LocalDate dueBy = on.plusDays(settings.termsFor(sheetId, person.gradeOn(on), on));
434	        Claim draft = new Claim(sheetId, personId, amount, on, note, dueBy);
435	        draft.setCorrects(corrects);
436	        Claim claim = claims.saveAndFlush(draft);
437	        logStatus(sheetId, user, person, claim);
438	        claim = claims.saveAndFlush(claim);
439	        record("CLAIM_ADDED", sheetId, user, person, claim);
440	        rollup.recordChanges(sheetId, user, before);
441	        return claim;
442	    }
443	
444	    @Transactional
445	    public Claim edit(String sheetId, String user, Long id, BigDecimal amount, LocalDate date, String note,
446	            String corrects) {
447	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
448	        if (claim.getStatus() != ClaimStatus.DRAFT) {
449	            throw new ClaimStatusRefusedException();
450	        }
451	        RollupService.Snapshot before = rollup.snapshot(sheetId);
452	        LocalDate on = dateOrToday(sheetId, date);
453	        refuseIfClosed(sheetId, claim.getDate());
454	        refuseIfClosed(sheetId, on);
455	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
456	        if (!person.mayClaimOn(on)) throw new PersonRetiredException();
457	        refuseUnlessCorrects(sheetId, person.getId(), amount, corrects);
458	        claim.setAmount(amount);
459	        claim.setCorrects(corrects);
460	        claim.setDate(on);
461	        claim.setNote(note);
462	        Claim saved = claims.saveAndFlush(claim);
463	        record("CLAIM_EDITED", sheetId, user, person, saved);
464	        rollup.recordChanges(sheetId, user, before);
465	        return saved;
466	    }
467	
468	    @Transactional
469	    public Claim changeStatus(String sheetId, String user, Long id, ClaimStatus next) {
470	        // Opening takes the sheet's next number, locking the sheet first so the claim is read only
471	        // once no other open on the sheet is under way; a refusal rolls the number back.
472	        Sheet numbering = next == ClaimStatus.OPEN ? sheets.lockForNumbering(sheetId) : null;
473	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
474	        if (!claim.getStatus().canBecome(next)) {
475	            throw new ClaimStatusRefusedException();
476	        }
477	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
478	            throw new ClaimDeferredException();
479	        }
480	        if (next == ClaimStatus.SETTLED && user.strip().equals(claim.getOpenedBy())) {
481	            throw new ClaimSettledByOpenerException();
482	        }
483	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
484	        // Settling freezes the late charge of the moment into the settled due.
485	        BigDecimal settling = next == ClaimStatus.SETTLED ? chargedFigureOf(sheetId, person, claim) : null;
486	        if (next == ClaimStatus.SETTLED && overClerkLimit(sheetId, user, settling)) next = ClaimStatus.PENDING;
487	        RollupService.Snapshot before = rollup.snapshot(sheetId);
488	        refuseIfClosed(sheetId, claim.getDate());
489	        switch (next) {
490	            case OPEN -> {
491	                number(numbering, claim);
492	                claim.setOpenedBy(user.strip());
493	            }
494	            case SETTLED -> claim.setSettledDue(settling);
495	            default -> {}
496	        }
497	        claim.setStatus(next);
498	        logStatus(sheetId, user, person, claim);
499	        Claim saved = claims.saveAndFlush(claim);
500	        String event = switch (next) {
501	            case OPEN -> "CLAIM_OPENED";
502	            case PENDING -> "CLAIM_PENDING";
503	            case SETTLED -> "CLAIM_SETTLED";
504	            case VOID -> "CLAIM_VOIDED";
505	            case DRAFT -> throw new IllegalStateException();
506	        };
507	        String due = next == ClaimStatus.SETTLED
508	                ? " due=" + (saved.getSettledDue() == null ? "n/a" : saved.getSettledDue().setScale(2).toPlainString())
509	                : "";
510	        record(event, sheetId, user, person, saved, saved.getNumber(), due);
511	        rollup.recordChanges(sheetId, user, before);
512	        return saved;
513	    }
514	
515	    /** A steward other than its opener approves a PENDING claim: SETTLED, its due fixed at its live due now. */
516	    @Transactional
517	    public Claim approve(String sheetId, String user, Long id) {
518	        // The snapshot locks the sheet first, so the claim is read once no other change is under way.
519	        RollupService.Snapshot before = rollup.snapshot(sheetId);
520	        Claim claim = pendingForSteward(sheetId, user, id);
521	        if (user.strip().equals(claim.getOpenedBy())) throw new ClaimApprovedByOpenerException();
522	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
523	        refuseIfClosed(sheetId, claim.getDate());
524	        claim.setSettledDue(chargedFigureOf(sheetId, person, claim));
525	        claim.setStatus(ClaimStatus.SETTLED);
526	        logStatus(sheetId, user, person, claim);
527	        Claim saved = claims.saveAndFlush(claim);
528	        record("CLAIM_APPROVED", sheetId, user, person, saved, saved.getNumber(), " due="
529	                + (saved.getSettledDue() == null ? "n/a" : saved.getSettledDue().setScale(2).toPlainString()));
530	        rollup.recordChanges(sheetId, user, before);
531	        return saved;
532	    }
533	
534	    /** A steward rejects a PENDING claim with a reason: OPEN again, bound by its person's last statement if it was. */
535	    @Transactional
536	    public Claim reject(String sheetId, String user, Long id, String reason) {
537	        // The snapshot locks the sheet first, so the claim is read once no other change is under way.
538	        RollupService.Snapshot before = rollup.snapshot(sheetId);
539	        Claim claim = pendingForSteward(sheetId, user, id);
540	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
541	        refuseIfClosed(sheetId, claim.getDate());
542	        claim.setStatus(ClaimStatus.OPEN);
543	        logStatus(sheetId, user, person, claim);
544	        Claim saved = claims.saveAndFlush(claim);
545	        record("CLAIM_REJECTED", sheetId, user, person, saved, saved.getNumber(), " reason=" + reason);
546	        rollup.recordChanges(sheetId, user, before);
547	        return saved;
548	    }
549	
550	    /**
551	     * A steward re-settles a SETTLED claim: its due fixed again at the figure it would have today as an
552	     * open claim bound by no statement (the rate, grade, floor and late percent in force on its date, the
553	     * late charge as of today). Refused for anyone
554	     * else, a claim in any other status, or one dated inside a closed period.
555	     */
556	    @Transactional
557	    public Claim resettle(String sheetId, String user, Long id) {
558	        // The snapshot locks the sheet first, so the claim is read once no other change is under way.
559	        RollupService.Snapshot before = rollup.snapshot(sheetId);
560	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
561	        if (claim.getStatus() != ClaimStatus.SETTLED) throw new ClaimStatusRefusedException();
562	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
563	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
564	        refuseIfClosed(sheetId, claim.getDate());
565	        BigDecimal old = claim.getSettledDue();
566	        BigDecimal figure = LateCharge.withChargeAsOpen(claim, dueOf(sheetId, person, claim), sheets.today(sheetId),
567	                settings.latePctOn(sheetId, claim.getDate()), roundingOf(sheetId, claim));
568	        claim.setSettledDue(figure);
569	        logStatus(sheetId, user, person, claim);
570	        Claim saved = claims.saveAndFlush(claim);
571	        record("CLAIM_RESETTLED", sheetId, user, person, saved, saved.getNumber(),
572	                " old=" + figureText(old) + " new=" + figureText(figure));
573	        rollup.recordChanges(sheetId, user, before);
574	        return saved;
575	    }
576	
577	    /** A fixed due as an audit line has it: two decimals, or n/a when none. */
578	    private static String figureText(BigDecimal due) {
579	        return due == null ? "n/a" : due.setScale(2).toPlainString();
580	    }
581	
582	    /**
583	     * A steward moves a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its number
584	     * and date, loses any figure a statement bound it to (live again until its new person's next
585	     * statement), and is listed as its new person's newest claim. A SETTLED or VOID claim cannot move,
586	     * nor one dated inside a closed period, nor one dated after its new person's retirement date.
587	     */
588	    @Transactional
589	    public Claim reassign(String sheetId, String user, Long id, Long toPersonId) {
590	        // The snapshot locks the sheet first, so the claim is read once no other change is under way.
591	        RollupService.Snapshot before = rollup.snapshot(sheetId);
592	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
593	        ClaimStatus status = claim.getStatus();
594	        if (status != ClaimStatus.DRAFT && !status.isOpen()) throw new ClaimStatusRefusedException();
595	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
596	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
597	        Person to = people.findByIdAndSheetId(toPersonId, sheetId).orElseThrow(PersonNotFoundException::new);
598	        if (from.getId().equals(to.getId())) throw new ClaimReassignRefusedException();
599	        refuseIfClosed(sheetId, claim.getDate());
600	        if (!to.mayClaimOn(claim.getDate())) throw new PersonRetiredException();
601	        claim.unstate();
602	        claim.moveTo(to.getId(), claims.nextListed());
603	        Claim saved = claims.saveAndFlush(claim);
604	        record("CLAIM_REASSIGNED", sheetId, user, to, saved, saved.getNumber(),
605	                " from=" + from.getName() + " to=" + to.getName());
606	        rollup.recordChanges(sheetId, user, before);
607	        return saved;
608	    }
609	
610	    /**
611	     * Defer an OPEN claim until a date after the sheet's today: until the sheet's today reaches it the claim
612	     * counts in no total, is not overdue, cannot be settled and is left unbound by a statement. Refused for a
613	     * claim that is not OPEN, a date not after today, or a claim dated inside a closed period.
614	     */
615	    @Transactional
616	    public Claim defer(String sheetId, String user, Long id, LocalDate until) {
617	        // The snapshot locks the sheet first, so the claim is read once no other change is under way.
618	        RollupService.Snapshot before = rollup.snapshot(sheetId);
619	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
620	        if (claim.getStatus() != ClaimStatus.OPEN) throw new ClaimStatusRefusedException();
621	        if (!until.isAfter(sheets.today(sheetId))) throw new ClaimDeferDateException();
622	        refuseIfClosed(sheetId, claim.getDate());
623	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
624	        claim.setDeferredUntil(until);
625	        Claim saved = claims.saveAndFlush(claim);
626	        record("CLAIM_DEFERRED", sheetId, user, person, saved, saved.getNumber(), " until=" + until);
627	        rollup.recordChanges(sheetId, user, before);
628	        return saved;
629	    }
630	
631	    /** The PENDING claim a steward approves or rejects; refused when not PENDING or not a steward. */
632	    private Claim pendingForSteward(String sheetId, String user, Long id) {
633	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
634	        if (claim.getStatus() != ClaimStatus.PENDING) throw new ClaimStatusRefusedException();
635	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
636	        return claim;
637	    }
638	
639	    /**
640	     * Give an opened claim its number: the sheet's next, or while the sheet numbers by period, the next
641	     * within the period its date falls in (in no period: the next in the sheet's X sequence).
642	     */
643	    private void number(Sheet sheet, Claim claim) {
644	        if (!sheet.numbersByPeriod()) {
645	            claim.setNumber(sheet.nextClaimNumber());
646	            return;
647	        }
648	        String period = periods.findBySheetIdOrderByFromDateAsc(sheet.getId()).stream()
649	                .filter(p -> p.contains(claim.getDate()))
650	                .map(Period::getName)
651	                .findFirst().orElse("");
652	        claim.setNumberWithin(period, claims.lastNumberWithin(sheet.getId(), period) + 1);
653	    }
654	
655	    /**
656	     * A claim's figure now: the due fixed when it was settled, else the due bound by its person's
657	     * last statement, else its live due; null when it has none.
658	     */
659	    public BigDecimal figureOf(String sheetId, Person person, Claim claim) {
660	        if (claim.getSettledDue() != null) return claim.getSettledDue();
661	        if (claim.isBound()) return claim.getStatedDue();
662	        return dueOf(sheetId, person, claim);
663	    }
664	
665	    /**
666	     * A claim's due now: its figure, with the late charge on top while it is overdue; null when it
667	     * has none. A statement binds the figure, never the charge.
668	     */
669	    public BigDecimal chargedFigureOf(String sheetId, Person person, Claim claim) {
670	        BigDecimal figure = figureOf(sheetId, person, claim);
671	        if (claim.getSettledDue() != null) return figure;
672	        return LateCharge.withCharge(claim, figure, sheets.today(sheetId),
673	                settings.latePctOn(sheetId, claim.getDate()), roundingOf(sheetId, claim));
674	    }
675	
676	    /** How the claim's live figures round: by its date, or a correction's by its corrected claim's ({@link Rounding}). */
677	    private RoundingMode roundingOf(String sheetId, Claim claim) {
678	        LocalDate basis = Rounding.basisOf(claim,
679	                Rounding.datesByNumber(claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, claim.getPersonId())));
680	        return Rounding.of(basis, settings.policyDate(sheetId), sheets.today(sheetId));
681	    }
682	
683	    /**
684	     * A claim's live due: its amount times the rate on its date of its person's grade in force on it, rounded to
685	     * cents as {@link Rounding} has it, and at least the sheet's floor in force on its date unless a correction; null with no rate.
686	     */
687	    private BigDecimal dueOf(String sheetId, Person person, Claim claim) {
688	        BigDecimal floor = claim.isCorrection() ? null : settings.floorOn(sheetId, claim.getDate());
689	        RoundingMode rounding = roundingOf(sheetId, claim);
690	        return rates.on(sheetId, person.gradeOn(claim.getDate()), claim.getDate())
691	                .map(Rate::getPct)
692	                .map(pct -> claim.getAmount().multiply(pct).movePointLeft(2).setScale(2, rounding))
693	                .map(due -> floor == null ? due : due.max(floor))
694	                .orElse(null);
695	    }
696	
697	    /** Log the status the claim now has: by the user on the sheet's today, with its due at this moment. */
698	    private void logStatus(String sheetId, String user, Person person, Claim claim) {
699	        claim.logStatus(user.strip(), sheets.today(sheetId), chargedFigureOf(sheetId, person, claim));
700	    }
701	
702	    private void record(String event, String sheetId, String user, Person person, Claim claim) {
703	        record(event, sheetId, user, person, claim, claim.getNumber(), "");
704	    }
705	
706	    /** A claim's audit line; one about a claim with a number has it, then any extra fields. */
707	    private void record(String event, String sheetId, String user, Person person, Claim claim, String number,
708	            String extra) {
709	        audit.recordOnCommit(event + " sheet=" + sheetId + " by=" + user.strip() + " person=" + person.getName()
710	                + " amount=" + claim.getAmount().setScale(2).toPlainString() + " date=" + claim.getDate()
711	                + (number != null ? " number=" + number : "") + extra);
712	    }
713	
714	    /**
715	     * Refuse a correction that names no SETTLED claim of its person by number, and a claim that names
716	     * one but is not a correction.
717	     */
718	    private void refuseUnlessCorrects(String sheetId, Long personId, BigDecimal amount, String corrects) {
719	        if (amount.signum() >= 0) {
720	            if (corrects != null) throw new CorrectionRefusedException();
721	            return;
722	        }
723	        boolean settled = corrects != null && claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId).stream()
724	                .anyMatch(c -> corrects.equals(c.getNumber()) && c.getStatus() == ClaimStatus.SETTLED);
725	        if (!settled) throw new CorrectionRefusedException();
726	    }
727	
728	    /** Whether a clerk settles a claim whose due is above the clerk limit; a due of n/a is within any. */
729	    private boolean overClerkLimit(String sheetId, String user, BigDecimal due) {
730	        if (settings.roleOf(sheetId, user) == Role.STEWARD) return false;
731	        BigDecimal limit = settings.clerkLimit(sheetId);
732	        return limit != null && due != null && due.compareTo(limit) > 0;
733	    }
734	
735	    /** Refuse a change to a claim dated inside a closed period; the caller holds the sheet's lock. */
736	    private void refuseIfClosed(String sheetId, LocalDate date) {
737	        if (periods.closedOn(sheetId, date)) throw new PeriodClosedException();
738	    }
739	
740	    private LocalDate dateOrToday(String sheetId, LocalDate date) {
741	        return date != null ? date : sheets.today(sheetId);
742	    }
743	}
