8	import org.springframework.stereotype.Service;
9	
10	/**
11	 * Changes to many selected claims at once. Each claim is changed in its own transaction, in list
12	 * order (people in the order they were added, each person's claims newest first), exactly as if
13	 * its own button were pressed; one that is refused is left as it is and counted as refused.
14	 */
15	@Service
16	public class ClaimBulkService {
17	
18	    /** How many of the selected claims went through, and how many were refused. */
19	    public record Result(int done, int refused) {}
20	
21	    private final ClaimService claims;
22	    private final ClaimRepository repository;
23	
24	    public ClaimBulkService(ClaimService claims, ClaimRepository repository) {
25	        this.claims = claims;
26	        this.repository = repository;
27	    }
28	
29	    /** Open each selected claim that can be opened, numbering them in list order. */
30	    public Result open(String sheetId, String user, Set<Long> ids) {
31	        return change(sheetId, user, ids, ClaimStatus.OPEN);
32	    }
33	
34	    /**
35	     * Settle each selected claim that can be settled, by the rules of settling one: a claim over
36	     * the user's clerk limit goes to PENDING and counts as settled.
37	     */
38	    public Result settle(String sheetId, String user, Set<Long> ids) {
39	        return change(sheetId, user, ids, ClaimStatus.SETTLED);
40	    }
41	
42	    private Result change(String sheetId, String user, Set<Long> ids, ClaimStatus next) {
43	        List<Claim> selected = repository.findBySheetIdOrderByListedDesc(sheetId).stream()
44	                .filter(c -> ids.contains(c.getId()))
45	                .sorted(Comparator.comparing(Claim::getPersonId).thenComparing(Claim::getListed, Comparator.reverseOrder()))
46	                .toList();
47	        int done = 0;
48	        for (Claim claim : selected) {
49	            try {
50	                claims.changeStatus(sheetId, user, claim.getId(), next);
51	                done++;
52	            } catch (ClaimStatusRefusedException | ClaimSettledByOpenerException | ClaimDeferredException | PeriodClosedException
53	                    | ClaimNotFoundException | PersonNotFoundException refused) {
54	                // left as it is
55	            }
56	        }
57	        return new Result(done, ids.size() - done);
58	    }
59	}
60	package net.officefloor.hq.app.claim;
61	
62	import java.math.BigDecimal;
63	import java.time.LocalDate;
64	import java.time.format.DateTimeParseException;
65	import java.util.ArrayList;
66	import java.util.List;
67	import java.util.regex.Pattern;
68	import net.officefloor.hq.app.person.Person;
69	import net.officefloor.hq.app.person.PersonRepository;
70	import org.springframework.stereotype.Service;
71	import org.springframework.transaction.annotation.Transactional;
72	
73	/**
74	 * Pasted claims: lines of name,amount,date,note (the note may hold commas and may be absent; a blank
75	 * date is the sheet's today), each a DRAFT claim for the person of the name on the sheet (ignoring
76	 * case and surrounding spaces), added in order exactly as the claim form adds one. Blank lines are
77	 * skipped; a paste with no line is refused. It is one change: a line that is refused refuses them all.
78	 */
79	@Service
80	public class ClaimPasteService {
81	
82	    /** The claim form's amount: up to two decimals, negative only for a correction (which a paste cannot name). */
83	    private static final Pattern AMOUNT = Pattern.compile("-?\\d{1,12}(\\.\\d{1,2})?");
84	    private static final int NOTE_MAX = 500;
85	
86	    private record Line(Long personId, BigDecimal amount, LocalDate date, String note) {}
87	
88	    private final ClaimService claims;
89	    private final PersonRepository people;
90	
91	    public ClaimPasteService(ClaimService claims, PersonRepository people) {
92	        this.claims = claims;
93	        this.people = people;
94	    }
95	
96	    @Transactional
97	    public List<Claim> paste(String sheetId, String user, String text) {
98	        List<Line> lines = new ArrayList<>();
99	        for (String raw : text.split("\\R")) {
100	            if (raw.isBlank()) continue;
101	            lines.add(parse(sheetId, raw));
102	        }
103	        if (lines.isEmpty()) throw new ClaimPasteRefusedException();
104	        List<Claim> added = new ArrayList<>();
105	        for (Line line : lines) {
106	            added.add(claims.add(sheetId, user, line.personId(), line.amount(), line.date(), line.note(), null));
107	        }
108	        return added;
109	    }
110	
111	    private Line parse(String sheetId, String raw) {
112	        String[] fields = raw.split(",", 4);
113	        if (fields.length < 3) throw new ClaimPasteRefusedException();
114	        String name = fields[0].strip();
115	        String amount = fields[1].strip();
116	        String date = fields[2].strip();
117	        String note = fields.length == 4 ? fields[3].strip() : "";
118	        if (name.isEmpty() || !AMOUNT.matcher(amount).matches() || note.length() > NOTE_MAX) {
119	            throw new ClaimPasteRefusedException();
120	        }
121	        Person person = people.findBySheetIdAndNameKey(sheetId, Person.keyOf(name))
122	                .orElseThrow(ClaimPasteRefusedException::new);
123	        LocalDate on;
124	        try {
125	            on = date.isEmpty() ? null : LocalDate.parse(date);
126	        } catch (DateTimeParseException e) {
127	            throw new ClaimPasteRefusedException();
128	        }
129	        return new Line(person.getId(), new BigDecimal(amount).setScale(2), on, note);
130	    }
131	}
