178	package net.officefloor.hq.app.rollup;
179	
180	import java.math.BigDecimal;
181	import java.math.RoundingMode;
182	import java.time.LocalDate;
183	import java.util.ArrayList;
184	import java.util.LinkedHashMap;
185	import java.util.List;
186	import java.util.Map;
187	import java.util.Objects;
188	import net.officefloor.hq.app.Audit;
189	import net.officefloor.hq.app.claim.Claim;
190	import net.officefloor.hq.app.claim.ClaimRepository;
191	import net.officefloor.hq.app.claim.LateCharge;
192	import net.officefloor.hq.app.claim.Rounding;
193	import net.officefloor.hq.app.person.Person;
194	import net.officefloor.hq.app.person.PersonRepository;
195	import net.officefloor.hq.app.rate.Rate;
196	import net.officefloor.hq.app.rate.RateRepository;
197	import net.officefloor.hq.app.sheet.Sheet;
198	import net.officefloor.hq.app.sheet.SheetRepository;
199	import org.springframework.stereotype.Service;
200	
201	/**
202	 * The sheet's figures as the screen shows them: each person's claimed and due-total, and the
203	 * sheet's claimed-total and due-total, each person's at most the sheet's cap in force today; a claim's floor and late percent are those in force on its date; an overdue claim's due has its {@link LateCharge} on top. A change takes a {@link #snapshot} before it alters
204	 * anything and calls {@link #recordChanges} once it has, which audits, after the change's own
205	 * lines, a ROLLUP line for each person whose figures (overdue-total included) moved (in the order
206	 * they were added) and a TOTALS line when the sheet's totals moved.
207	 */
208	@Service
209	public class RollupService {
210	
211	    /** A person's figures; a null due-total is n/a; the overdue-total is the dues of their overdue claims. */
212	    public record Figures(String name, BigDecimal claimed, BigDecimal dueTotal, BigDecimal overdueTotal) {
213	        boolean sameAs(Figures other) {
214	            return other != null && claimed.compareTo(other.claimed) == 0 && Objects.equals(dueTotal, other.dueTotal)
215	                    && overdueTotal.compareTo(other.overdueTotal) == 0;
216	        }
217	    }
218	
219	    /** The sheet's figures at a moment: each person's, by id in the order they were added, and the totals. */
220	    public record Snapshot(Map<Long, Figures> people, BigDecimal claimedTotal, BigDecimal dueTotal,
221	            BigDecimal overdueTotal) {}
222	
223	    private final PersonRepository people;
224	    private final ClaimRepository claims;
225	    private final RateRepository rates;
226	    private final SheetRepository sheets;
227	    private final Audit audit;
228	
229	    public RollupService(PersonRepository people, ClaimRepository claims, RateRepository rates,
230	            SheetRepository sheets, Audit audit) {
231	        this.people = people;
232	        this.claims = claims;
233	        this.rates = rates;
234	        this.sheets = sheets;
235	        this.audit = audit;
236	    }
237	
238	    /**
239	     * The sheet's figures now. Locks the sheet until the caller's transaction ends, so no other
240	     * change on the sheet moves the figures between this snapshot and the one after the change.
241	     */
242	    public Snapshot snapshot(String sheetId) {
243	        Sheet sheet = sheets.findForUpdate(sheetId).orElse(null);
244	        LocalDate today = sheet == null ? null : sheet.getToday();
245	        LocalDate policyDate = sheet == null ? null : sheet.getPolicyDate();
246	        Map<String, List<Rate>> ratesByGrade = new LinkedHashMap<>();
247	        for (Rate rate : rates.findBySheetIdOrderByGradeAscFromDateAsc(sheetId)) {
248	            ratesByGrade.computeIfAbsent(rate.getGrade(), g -> new ArrayList<>()).add(rate);
249	        }
250	        Map<Long, List<Claim>> claimsByPerson = new LinkedHashMap<>();
251	        List<Claim> all = claims.findBySheetIdOrderByIdDesc(sheetId);
252	        Map<String, LocalDate> datesByNumber = Rounding.datesByNumber(all);
253	        for (Claim claim : all) {
254	            if (claim.getStatus().counts()) {
255	                claimsByPerson.computeIfAbsent(claim.getPersonId(), id -> new ArrayList<>()).add(claim);
256	            }
257	        }
258	        Map<Long, Figures> figures = new LinkedHashMap<>();
259	        BigDecimal claimedTotal = zero();
260	        BigDecimal dueTotal = zero();
261	        BigDecimal overdueTotal = zero();
262	        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
263	            BigDecimal claimed = zero();
264	            BigDecimal due = zero();
265	            BigDecimal overdue = zero();
266	            boolean fixed = false;
267	            for (Claim claim : claimsByPerson.getOrDefault(person.getId(), List.of())) {
268	                if (!person.counts(claim, today)) continue;
269	                claimed = claimed.add(claim.getAmount());
270	                if (claim.getSettledDue() != null || (claim.isBound() && claim.getStatedDue() != null)) fixed = true;
271	                String grade = person.gradeOn(claim.getDate());
272	                RoundingMode rounding = Rounding.of(Rounding.basisOf(claim, datesByNumber), policyDate, today);
273	                // the floor and late percent in force on the claim's date
274	                BigDecimal floor = sheet == null ? zero() : sheet.floorOn(claim.getDate());
275	                BigDecimal latePct = sheet == null ? zero() : sheet.latePctOn(claim.getDate());
276	                BigDecimal figure = LateCharge.withCharge(claim,
277	                        figureOf(claim, ratesByGrade.getOrDefault(grade, List.of()), floor, rounding), today,
278	                        latePct, rounding);
279	                // a due under a grade they had on its date but not today counts like a fixed one
280	                if (figure != null && today != null && !grade.equals(person.gradeOn(today))) fixed = true;
281	                // and so does a due under a rate that is not the one in force today
282	                if (figure != null && today != null && !Rate.inForce(ratesByGrade.getOrDefault(grade, List.of()),
283	                        claim.getDate()).equals(Rate.inForce(ratesByGrade.getOrDefault(grade, List.of()), today))) fixed = true;
284	                if (figure != null) due = due.add(figure);
285	                if (figure != null && LateCharge.isOverdue(claim, today)) overdue = overdue.add(figure);
286	            }
287	            // As on screen: n/a when their grade has no rate today and none of the counted claims has a fixed
288	            // due, nor a due under another grade they had on its date or under a rate not in force today.
289	            boolean rated = today != null
290	                    && pctOn(ratesByGrade.getOrDefault(person.gradeOn(today), List.of()), today) != null;
291	            BigDecimal personDue = fixed || rated ? due : null;
292	            if (sheet != null) personDue = sheet.capped(personDue);
293	            figures.put(person.getId(), new Figures(person.getName(), claimed, personDue, overdue));
294	            claimedTotal = claimedTotal.add(claimed);
295	            if (personDue != null) dueTotal = dueTotal.add(personDue);
296	            overdueTotal = overdueTotal.add(overdue);
297	        }
298	        return new Snapshot(figures, claimedTotal, dueTotal, overdueTotal);
299	    }
300	
301	    /** Audit, once the transaction commits, how the sheet's figures moved since {@code before}. */
302	    public void recordChanges(String sheetId, String user, Snapshot before) {
303	        Snapshot after = snapshot(sheetId);
304	        String by = " sheet=" + sheetId + " by=" + user.strip();
305	        for (Map.Entry<Long, Figures> e : after.people().entrySet()) {
306	            Figures now = e.getValue();
307	            if (now.sameAs(before.people().get(e.getKey()))) continue;
308	            audit.recordOnCommit("ROLLUP" + by + " person=" + now.name() + " claimed=" + money(now.claimed())
309	                    + " due-total=" + (now.dueTotal() == null ? "n/a" : money(now.dueTotal()))
310	                    + " overdue-total=" + money(now.overdueTotal()));
311	        }
312	        if (after.claimedTotal().compareTo(before.claimedTotal()) != 0
313	                || after.dueTotal().compareTo(before.dueTotal()) != 0
314	                || after.overdueTotal().compareTo(before.overdueTotal()) != 0) {
315	            audit.recordOnCommit("TOTALS" + by + " claimed-total=" + money(after.claimedTotal())
316	                    + " due-total=" + money(after.dueTotal())
317	                    + " overdue-total=" + money(after.overdueTotal()));
318	        }
319	    }
320	
321	    /**
322	     * A claim's figure: its settled due, else its stated due, else its live due, at least the floor
323	     * unless a correction, rounded as given; null when it has none.
324	     */
325	    private static BigDecimal figureOf(Claim claim, List<Rate> rates, BigDecimal floor, RoundingMode rounding) {
326	        if (claim.getSettledDue() != null) return claim.getSettledDue();
327	        if (claim.isBound()) return claim.getStatedDue();
328	        BigDecimal pct = pctOn(rates, claim.getDate());
329	        if (pct == null) return null;
330	        BigDecimal due = claim.getAmount().multiply(pct).movePointLeft(2).setScale(2, rounding);
331	        return claim.isCorrection() ? due : due.max(floor);
332	    }
333	
334	    /** Of one grade's rates, the percent in force on the date, or null. */
335	    private static BigDecimal pctOn(List<Rate> rates, LocalDate date) {
336	        return Rate.inForce(rates, date)
337	                .map(Rate::getPct)
338	                .orElse(null);
339	    }
340	
341	    private static BigDecimal zero() {
342	        return BigDecimal.ZERO.setScale(2);
343	    }
344	
345	    private static String money(BigDecimal value) {
346	        return value.setScale(2).toPlainString();
347	    }
348	}
