351	import jakarta.persistence.CollectionTable;
352	import jakarta.persistence.Column;
353	import jakarta.persistence.ElementCollection;
354	import jakarta.persistence.Entity;
355	import jakarta.persistence.FetchType;
356	import jakarta.persistence.GeneratedValue;
357	import jakarta.persistence.GenerationType;
358	import jakarta.persistence.Id;
359	import jakarta.persistence.JoinColumn;
360	import jakarta.persistence.MapKeyColumn;
361	import jakarta.persistence.OrderBy;
362	import jakarta.persistence.Table;
363	import jakarta.persistence.Version;
364	import java.time.LocalDate;
365	import java.util.ArrayList;
366	import java.util.List;
367	import java.util.Locale;
368	import java.util.Map;
369	import java.util.TreeMap;
370	import net.officefloor.hq.app.claim.Claim;
371	
372	/**
373	 * A person on a sheet, with a name and a grade (A, B or C). The name is kept without surrounding
374	 * spaces and is unique on the sheet without regard to case (by its {@link #keyOf key}). A person
375	 * given a retirement date is retired at once, whatever the date; none of their claims may be dated
376	 * after it. A person may have several holds over time, each from a from-date to an optional to-date. The grade is dated: the first one
377	 * given is in force from the beginning of time, and each later one from its from-date.
378	 */
379	@Entity
380	@Table(name = "person")
381	public class Person {
382	
383	    @Id
384	    @GeneratedValue(strategy = GenerationType.IDENTITY)
385	    private Long id;
386	
387	    @Column(name = "sheet_id", nullable = false)
388	    private String sheetId;
389	
390	    @Column(name = "name", nullable = false)
391	    private String name;
392	
393	    @Column(name = "name_key", nullable = false)
394	    private String nameKey;
395	
396	    @Column(name = "grade", nullable = false)
397	    private String grade;
398	
399	    /** The grades recorded after the first, by the date each is in force from. */
400	    @ElementCollection(fetch = FetchType.EAGER)
401	    @CollectionTable(name = "person_grade", joinColumns = @JoinColumn(name = "person_id"))
402	    @MapKeyColumn(name = "from_date")
403	    @Column(name = "grade", nullable = false)
404	    private Map<LocalDate, String> datedGrades = new TreeMap<>();
405	
406	    @Column(name = "retired_from")
407	    private LocalDate retiredFrom;
408	
409	    /** Their holds, earliest from-date first. */
410	    @ElementCollection(fetch = FetchType.EAGER)
411	    @CollectionTable(name = "person_hold", joinColumns = @JoinColumn(name = "person_id"))
412	    @OrderBy("fromDate ASC, toDate ASC")
413	    private List<PersonHold> holds = new ArrayList<>();
414	
415	    @Version
416	    @Column(name = "version", nullable = false)
417	    private long version;
418	
419	    protected Person() {}
420	
421	    public Person(String sheetId, String name, String grade) {
422	        this.sheetId = sheetId;
423	        setName(name);
424	        this.grade = grade;
425	    }
426	
427	    /** The key a name is compared by for uniqueness: without surrounding spaces, lower-cased. */
428	    public static String keyOf(String name) {
429	        return name.strip().toLowerCase(Locale.ROOT);
430	    }
431	
432	    public Long getId() { return id; }
433	
434	    public String getSheetId() { return sheetId; }
435	
436	    public String getName() { return name; }
437	
438	    public void setName(String name) {
439	        this.name = name.strip();
440	        this.nameKey = keyOf(name);
441	    }
442	
443	    /** The first grade they were given, in force from the beginning of time. */
444	    public String getGrade() { return grade; }
445	
446	    /** The grade in force on the date: the one with the latest from-date on or before it. */
447	    public String gradeOn(LocalDate date) {
448	        Map.Entry<LocalDate, String> on = new TreeMap<>(datedGrades).floorEntry(date);
449	        return on == null ? grade : on.getValue();
450	    }
451	
452	    /** Record the grade from the date, in place of any recorded from the same date. */
453	    public void setGradeFrom(LocalDate from, String grade) { datedGrades.put(from, grade); }
454	
455	    /** The grades recorded after the first, by the date each is in force from, earliest first. */
456	    public Map<LocalDate, String> getDatedGrades() { return new TreeMap<>(datedGrades); }
457	
458	    /** The date they are retired from, or null while not retired. */
459	    public LocalDate getRetiredFrom() { return retiredFrom; }
460	
461	    public void setRetiredFrom(LocalDate retiredFrom) { this.retiredFrom = retiredFrom; }
462	
463	    public boolean isRetired() { return retiredFrom != null; }
464	
465	    /** Whether a claim of theirs may be dated on the date: not after their retirement date. */
466	    public boolean mayClaimOn(LocalDate date) { return retiredFrom == null || !date.isAfter(retiredFrom); }
467	
468	    /** Whether they have any hold, whatever its dates. */
469	    public boolean isHeld() { return !holds.isEmpty(); }
470	
471	    /** Their holds, earliest from-date first. */
472	    public List<PersonHold> getHolds() { return List.copyOf(holds); }
473	
474	    public void addHold(PersonHold hold) { holds.add(hold); }
475	
476	    /** Whether the date falls within any of their holds. */
477	    public boolean heldOn(LocalDate date) { return holds.stream().anyMatch(h -> h.contains(date)); }
478	
479	    /**
480	     * Whether a claim of theirs counts in the live totals: it counts by its status, unless it is open
481	     * (OPEN or PENDING), dated within a hold and not bound by a statement, or deferred on the sheet's today.
482	     */
483	    public boolean counts(Claim claim, LocalDate today) {
484	        if (!claim.getStatus().counts() || claim.isDeferredOn(today)) return false;
485	        return !claim.getStatus().isOpen() || claim.isBound() || !heldOn(claim.getDate());
486	    }
487	
488	    /** Moved on by each save; an edit is refused unless made from the current version. */
489	    public long getVersion() { return version; }
490	}
