501	import net.officefloor.hq.app.sheet.SheetNotFoundException;
502	import net.officefloor.hq.app.sheet.SheetRepository;
503	import org.springframework.dao.DataIntegrityViolationException;
504	import org.springframework.orm.ObjectOptimisticLockingFailureException;
505	import org.springframework.stereotype.Service;
506	import org.springframework.transaction.annotation.Transactional;
507	
508	/**
509	 * The people on a sheet: listed in the order they were added, added and edited one at a time. A
510	 * name already used by another person on the sheet (ignoring case and surrounding spaces) is
511	 * refused, and so is an edit made from a version of the person someone else has saved since. A
512	 * person can be retired from a date (blank: the sheet's today), and put on hold from a from-date (blank: the sheet's today) to an optional to-date, any number of
513	 * times. A
514	 * person can name other people on the sheet as their patrons, one at a time; not themselves, and
515	 * not the same person twice. A person's grade is dated: the first one given is in force from the
516	 * beginning of time, and each edit records the grade from its from-date (blank: the sheet's today),
517	 * unless it leaves the grade as in force on the sheet's today with the from-date blank.
518	 */
519	@Service
520	public class PersonService {
521	
522	    private final PersonRepository people;
523	    private final PersonPatronRepository patrons;
524	    private final SheetRepository sheets;
525	    private final RollupService rollup;
526	    private final Audit audit;
527	
528	    public PersonService(PersonRepository people, PersonPatronRepository patrons, SheetRepository sheets,
529	            RollupService rollup, Audit audit) {
530	        this.people = people;
531	        this.patrons = patrons;
532	        this.sheets = sheets;
533	        this.rollup = rollup;
534	        this.audit = audit;
535	    }
536	
537	    @Transactional(readOnly = true)
538	    public List<Person> list(String sheetId) {
539	        return people.findBySheetIdOrderByIdAsc(sheetId);
540	    }
541	
542	    /** The sheet's today, or null when there is no such sheet. */
543	    @Transactional(readOnly = true)
544	    public LocalDate today(String sheetId) {
545	        return sheets.findById(sheetId).map(Sheet::getToday).orElse(null);
546	    }
547	
548	    @Transactional
549	    public Person add(String sheetId, String user, String name, String grade) {
550	        if (!sheets.existsById(sheetId)) throw new SheetNotFoundException();
551	        requireUnused(sheetId, name, null);
552	        RollupService.Snapshot before = rollup.snapshot(sheetId);
553	        Person person = saveUnique(new Person(sheetId, name, grade));
554	        record("PERSON_ADDED", sheetId, user, person, person.getGrade());
555	        rollup.recordChanges(sheetId, user, before);
556	        return person;
557	    }
