559	    @Transactional
560	    public Person edit(String sheetId, String user, Long id, long version, String name, String grade,
561	            LocalDate gradeFrom) {
562	        Person person = people.findByIdAndSheetId(id, sheetId).orElseThrow(PersonNotFoundException::new);
563	        if (person.getVersion() != version) throw new PersonVersionConflictException();
564	        requireUnused(sheetId, name, id);
565	        RollupService.Snapshot before = rollup.snapshot(sheetId);
566	        LocalDate today = today(sheetId);
567	        person.setName(name);
568	        if (gradeFrom != null || !grade.equals(person.gradeOn(today))) {
569	            person.setGradeFrom(gradeFrom != null ? gradeFrom : today, grade);
570	        }
571	        Person saved = saveUnique(person);
572	        record("PERSON_EDITED", sheetId, user, saved, saved.gradeOn(today));
573	        rollup.recordChanges(sheetId, user, before);
574	        return saved;
575	    }
576	
577	    @Transactional
578	    public Person retire(String sheetId, String user, Long id, LocalDate from) {
579	        // Lock the sheet so no claim is added or edited for them meanwhile against the old date.
580	        LocalDate today = sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new).getToday();
581	        Person person = people.findByIdAndSheetId(id, sheetId).orElseThrow(PersonNotFoundException::new);
582	        LocalDate on = from != null ? from : today;
583	        person.setRetiredFrom(on);
584	        Person saved = saveUnique(person);
585	        audit.recordOnCommit("PERSON_RETIRED sheet=" + sheetId + " by=" + user.strip()
586	                + " name=" + saved.getName() + " from=" + on);
587	        return saved;
588	    }
