590	    /**
591	     * Put the person on hold from the date (blank: the sheet's today) to the optional to-date; their
592	     * open (OPEN or PENDING) claims dated within it, unless bound by a statement, leave the totals.
593	     */
594	    @Transactional
595	    public Person hold(String sheetId, String user, Long id, LocalDate from, LocalDate to) {
596	        RollupService.Snapshot before = rollup.snapshot(sheetId);
597	        Person person = people.findByIdAndSheetId(id, sheetId).orElseThrow(PersonNotFoundException::new);
598	        LocalDate on = from != null ? from : today(sheetId);
599	        if (on == null) throw new SheetNotFoundException();
600	        if (to != null && to.isBefore(on)) throw new HoldDatesException();
601	        person.addHold(new PersonHold(on, to));
602	        Person saved = saveUnique(person);
603	        audit.recordOnCommit("PERSON_HELD sheet=" + sheetId + " by=" + user.strip()
604	                + " name=" + saved.getName() + " from=" + on);
605	        rollup.recordChanges(sheetId, user, before);
606	        return saved;
607	    }
608	
609	    /** Each person's patrons' ids on the sheet, by person id, in the order they were named. */
610	    @Transactional(readOnly = true)
611	    public Map<Long, List<Long>> patronIds(String sheetId) {
612	        Map<Long, List<Long>> by = new HashMap<>();
613	        for (PersonPatron p : patrons.findBySheetIdOrderByIdAsc(sheetId)) {
614	            by.computeIfAbsent(p.getPersonId(), k -> new ArrayList<>()).add(p.getPatronId());
615	        }
616	        return by;
617	    }
618	
619	    /** The person's patrons' ids, in the order they were named. */
620	    @Transactional(readOnly = true)
621	    public List<Long> patronIdsOf(Long personId) {
622	        return patrons.findByPersonIdOrderByIdAsc(personId).stream().map(PersonPatron::getPatronId).toList();
623	    }
624	
625	    /** Name another person on the sheet as the person's patron; not themselves, nor one already named. */
626	    @Transactional
627	    public Person addPatron(String sheetId, String user, Long id, Long patronId) {
628	        Person person = people.findByIdAndSheetId(id, sheetId).orElseThrow(PersonNotFoundException::new);
629	        Person patron = people.findByIdAndSheetId(patronId, sheetId).orElseThrow(PersonNotFoundException::new);
630	        if (person.getId().equals(patron.getId())) throw new PatronRefusedException();
631	        if (patrons.existsByPersonIdAndPatronId(person.getId(), patron.getId())) throw new PatronRefusedException();
632	        try {
633	            patrons.saveAndFlush(new PersonPatron(sheetId, person.getId(), patron.getId()));
634	        } catch (DataIntegrityViolationException e) {
635	            // named by another user meanwhile
636	            throw new PatronRefusedException();
637	        }
638	        audit.recordOnCommit("PATRON_ADDED sheet=" + sheetId + " by=" + user.strip()
639	                + " name=" + person.getName() + " patron=" + patron.getName());
640	        return person;
641	    }
642	
643	    private void record(String event, String sheetId, String user, Person person, String grade) {
644	        audit.recordOnCommit(event + " sheet=" + sheetId + " by=" + user.strip()
645	                + " name=" + person.getName() + " grade=" + grade);
646	    }
647	
648	    private void requireUnused(String sheetId, String name, Long self) {
649	        people.findBySheetIdAndNameKey(sheetId, Person.keyOf(name))
650	                .filter(other -> !other.getId().equals(self))
651	                .ifPresent(other -> { throw new DuplicatePersonNameException(); });
652	    }
653	
654	    /** Writes the person now, so a name taken meanwhile by another user is refused by the store. */
655	    private Person saveUnique(Person person) {
656	        try {
657	            return people.saveAndFlush(person);
658	        } catch (DataIntegrityViolationException e) {
659	            throw new DuplicatePersonNameException();
660	        } catch (ObjectOptimisticLockingFailureException e) {
661	            throw new PersonVersionConflictException();
662	        }
663	    }
664	}
