238	/**
239	 * The statements taken for people on a sheet. Taking one records the person's due-total at that
240	 * moment (late charges included, at most the sheet's cap) and binds each of their claims that counts to the figure it has
241	 * then, without its late charge, which keeps following the sheet's today; their other claims
242	 * are left unbound, their due live again. A claim's due fixed when settled stays as it is.
243	 */
244	@Service
245	public class StatementService {
246	
247	    /** A person's statements: how many, and the last one's due-total (null when n/a) and date. */
248	    public record Summary(Long personId, int count, BigDecimal lastDueTotal, LocalDate lastDate) {}
249	
250	    /** A statement just taken, with the person's claims as they now stand. */
251	    public record Taken(Summary summary, List<Claim> claims) {}
252	
253	    private final StatementRepository statements;
254	    private final PersonRepository people;
255	    private final ClaimRepository claims;
256	    private final ClaimService claimService;
257	    private final RateService rates;
258	    private final SheetRepository sheets;
259	    private final RollupService rollup;
260	    private final Audit audit;
261	
262	    public StatementService(StatementRepository statements, PersonRepository people, ClaimRepository claims,
263	            ClaimService claimService, RateService rates, SheetRepository sheets, RollupService rollup, Audit audit) {
264	        this.statements = statements;
265	        this.people = people;
266	        this.claims = claims;
267	        this.claimService = claimService;
268	        this.rates = rates;
269	        this.sheets = sheets;
270	        this.rollup = rollup;
271	        this.audit = audit;
272	    }
273	
274	    /** Each person's statements on the sheet, for those with any. */
275	    @Transactional(readOnly = true)
276	    public List<Summary> summaries(String sheetId) {
277	        Map<Long, List<Statement>> byPerson = new LinkedHashMap<>();
278	        for (Statement s : statements.findBySheetIdOrderByIdAsc(sheetId)) {
279	            byPerson.computeIfAbsent(s.getPersonId(), id -> new ArrayList<>()).add(s);
280	        }
281	        return byPerson.entrySet().stream().map(e -> summaryOf(e.getKey(), e.getValue())).toList();
282	    }
283	
284	    @Transactional
285	    public Taken take(String sheetId, String user, Long personId) {
286	        // Lock the sheet so the claims and rates read are not changed while the statement is taken.
287	        Sheet sheet = sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new);
288	        LocalDate today = sheet.getToday();
289	        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
290	        RollupService.Snapshot before = rollup.snapshot(sheetId);
291	        List<Claim> theirs = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId);
292	        boolean fixed = false;
293	        BigDecimal total = BigDecimal.ZERO.setScale(2);
294	        int counted = 0;
295	        for (Claim claim : theirs) {
296	            if (!person.counts(claim, today)) {
297	                claim.unstate();
298	                continue;
299	            }
300	            BigDecimal figure = claimService.figureOf(sheetId, person, claim);
301	            BigDecimal due = claimService.chargedFigureOf(sheetId, person, claim);
302	            if (claim.getSettledDue() != null || (claim.isBound() && claim.getStatedDue() != null)) fixed = true;
303	            // a due under a grade they had on its date but not today counts like a fixed one
304	            if (due != null && !person.gradeOn(claim.getDate()).equals(person.gradeOn(today))) fixed = true;
305	            // and so does a due under a rate that is not the one in force today
306	            String grade = person.gradeOn(claim.getDate());
307	            if (due != null && !rates.on(sheetId, grade, claim.getDate()).map(Rate::getId)
308	                    .equals(rates.on(sheetId, grade, today).map(Rate::getId))) fixed = true;
309	            claim.state(figure);
310	            if (due != null) total = total.add(due);
311	            counted++;
312	        }
313	        // As on screen: n/a when their grade has no rate today and none of the counted claims has a fixed
314	        // due, nor a due under another grade they had on its date or under a rate not in force today.
315	        BigDecimal dueTotal = sheet.capped(
316	                fixed || rates.on(sheetId, person.gradeOn(today), today).isPresent() ? total : null);
317	        claims.saveAllAndFlush(theirs);
318	        statements.saveAndFlush(new Statement(sheetId, personId, dueTotal, today, user.strip()));
319	        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user.strip() + " name=" + person.getName()
320	                + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.toPlainString()) + " claims=" + counted);
321	        rollup.recordChanges(sheetId, user, before);
322	        return new Taken(summaryOf(personId, statements.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId)),
323	                theirs);
324	    }
325	
326	    private static Summary summaryOf(Long personId, List<Statement> list) {
327	        Statement last = list.get(list.size() - 1);
328	        return new Summary(personId, list.size(), last.getDueTotal(), last.getDate());
329	    }
330	}
