405	/**
406	 * The sheet's rate for one grade from a date: a percent with two decimals (0.00 or more). A rate
407	 * with no from-date applies from the beginning of time; one with a to-date applies through it.
408	 */
409	@Entity
410	@Table(name = "rate")
411	public class Rate {
412	
413	    @Id
414	    @GeneratedValue(strategy = GenerationType.IDENTITY)
415	    private Long id;
416	
417	    @Column(name = "sheet_id", nullable = false)
418	    private String sheetId;
