442	    /**
443	     * Of one grade's rates, the one in force on the date: the one with the latest from-date on or
444	     * before it, unless the date is after that rate's to-date (then none).
445	     */
446	    public static Optional<Rate> inForce(Collection<Rate> rates, LocalDate date) {
447	        return rates.stream()
448	                .filter(rate -> rate.appliesOn(date))
449	                .max(Comparator.comparing(Rate::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
450	                .filter(rate -> rate.toDate == null || !date.isAfter(rate.toDate));
451	    }
