461	
462	    /** Whether it applies on the date: it has no from-date, or one on or before the date. */
463	    public boolean appliesOn(LocalDate date) { return fromDate == null || !fromDate.isAfter(date); }
464	
465	    /** The last date it applies on; null when it has no end. */
466	    public LocalDate getToDate() { return toDate; }
