486	
487	/**
488	 * The sheet's rates for each grade, each from a date (or from the beginning of time): set one grade
489	 * and from-date at a time, replacing any rate it had. A date's rate is the one with the latest
490	 * from-date on or before it.
491	 */
492	@Service
493	public class RateService {
494	
495	    private final RateRepository rates;
496	    private final SheetRepository sheets;
497	    private final RollupService rollup;
498	    private final Audit audit;
499	
500	    public RateService(RateRepository rates, SheetRepository sheets, RollupService rollup, Audit audit) {
501	        this.rates = rates;
502	        this.sheets = sheets;
503	        this.rollup = rollup;
504	        this.audit = audit;
505	    }
506	
507	    @Transactional(readOnly = true)
508	    public List<Rate> list(String sheetId) {
509	        return rates.findBySheetIdOrderByGradeAscFromDateAsc(sheetId);
510	    }
511	
512	    /** The grade's rate on the date: the one with the latest from-date on or before it, if any and not ended. */
513	    @Transactional(readOnly = true)
514	    public Optional<Rate> on(String sheetId, String grade, LocalDate date) {
515	        return Rate.inForce(rates.findBySheetIdAndGrade(sheetId, grade), date);
516	    }
517	
518	    @Transactional
519	    public Rate set(String sheetId, String user, String grade, LocalDate from, LocalDate to, BigDecimal pct) {
520	        if (to != null && from != null && to.isBefore(from)) throw new RateDatesException();
521	        // Lock the sheet so two users setting the same grade and from-date at once replace one rate.
522	        sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new);
523	        RollupService.Snapshot before = rollup.snapshot(sheetId);
524	        Optional<Rate> existing = from == null
525	                ? rates.findBySheetIdAndGradeAndFromDateIsNull(sheetId, grade)
526	                : rates.findBySheetIdAndGradeAndFromDate(sheetId, grade, from);
527	        Rate rate = existing.orElseGet(() -> new Rate(sheetId, grade, from, to, pct));
528	        rate.setPct(pct);
529	        rate.setToDate(to);
530	        Rate saved = rates.saveAndFlush(rate);
531	        audit.recordOnCommit("RATE_SET sheet=" + sheetId + " by=" + user.strip()
532	                + " grade=" + saved.getGrade() + " rate=" + saved.getPct().setScale(2).toPlainString()
533	                + (saved.getFromDate() != null ? " from=" + saved.getFromDate() : "")
534	                + (saved.getToDate() != null ? " to=" + saved.getToDate() : ""));
535	        rollup.recordChanges(sheetId, user, before);
536	        return saved;
537	    }
538	}
