556	/** A sheet, keyed by the id a user types; everything else in the app is kept per sheet. */
557	@Entity
558	@Table(name = "sheet")
559	public class Sheet {
560	
561	    /** The keys of its dated settings; a grade's terms are {@code terms-<grade>}. */
562	    public static final String FLOOR = "floor", LATE_PCT = "late-pct", TERMS = "terms", CLERK_LIMIT = "clerk-limit",
563	            CAP = "cap";
564	
565	    /** The values in force before any is recorded. */
566	    public static final BigDecimal START_FLOOR = new BigDecimal("1.00"), START_LATE_PCT = new BigDecimal("0.00");
567	    public static final int START_TERMS = 14;
568	
569	    @Id
570	    private String id;
571	
572	    @Column(name = "created_by", nullable = false)
573	    private String createdBy;
574	
575	    @Column(name = "created_at", nullable = false)
576	    private Instant createdAt;
577	
578	    /** The sheet's today: every date decision and default date on the sheet uses it. */
579	    @Column(name = "today", nullable = false)
580	    private LocalDate today;
581	
582	    /** The last claim number given on the sheet; the next claim opened takes the one after it. */
583	    @Column(name = "last_claim_number", nullable = false)
584	    private long lastClaimNumber;
585	
586	    /**
587	     * The values recorded for its dated settings, each from a from-date: the floor (a claim's live due
588	     * is at least the one in force on its date), the late percent (an overdue claim's due gains the one
589	     * in force on its date of its figure for every full 30 days overdue), the terms of the sheet and of
590	     * each grade (a claim's due-by is its date plus those in force on it), the clerk limit (a clerk can
591	     * settle a claim only when its due is at or below the one in force today) and the cap (a person's
592	     * due-total is at most the one in force today).
593	     */
594	    @ElementCollection(fetch = FetchType.EAGER)
595	    @CollectionTable(name = "sheet_setting", joinColumns = @JoinColumn(name = "sheet_id"))
596	    private List<DatedSetting> dated = new ArrayList<>();
597	
598	    /** A claim dated before it rounds half up, one on or after it half to even; null means the sheet's today. */
599	    @Column(name = "policy_date")
600	    private LocalDate policyDate;
601	
602	    /** While set and today is on or after it, a claim opened is numbered within its period; null means off. */
603	    @Column(name = "period_numbering_from")
604	    private LocalDate periodNumberingFrom;
605	
606	    protected Sheet() {}
607	
608	    public Sheet(String id, String createdBy, Instant createdAt, LocalDate today) {
609	        this.id = id;
610	        this.createdBy = createdBy;
611	        this.createdAt = createdAt;
612	        this.today = today;
613	    }
614	
615	    public String getId() { return id; }
616	
617	    public String getCreatedBy() { return createdBy; }
618	
619	    public Instant getCreatedAt() { return createdAt; }
620	
621	    public LocalDate getToday() { return today; }
622	
623	    public void setToday(LocalDate today) { this.today = today; }
624	
625	    /** The values recorded for its dated settings, by key and then from-date, earliest first. */
626	    public List<DatedSetting> getDated() {
627	        List<DatedSetting> sorted = new ArrayList<>(dated);
628	        sorted.sort(Comparator.comparing(DatedSetting::getKey).thenComparing(DatedSetting::getFrom));
629	        return sorted;
630	    }
631	
632	    /** Record the key's value (null: none) from the date on; a value already recorded from that date is replaced. */
633	    public void record(String key, LocalDate from, String value) {
634	        dated.removeIf(d -> d.getKey().equals(key) && d.getFrom().equals(from));
635	        dated.add(new DatedSetting(key, from, value));
636	    }
637	
638	    /** The key's value recorded with the latest from-date on or before the date; null when none is. */
639	    private DatedSetting inForce(String key, LocalDate date) {
640	        DatedSetting found = null;
641	        for (DatedSetting d : dated) {
642	            if (d.getKey().equals(key) && !d.getFrom().isAfter(date)
643	                    && (found == null || d.getFrom().isAfter(found.getFrom()))) {
644	                found = d;
645	            }
646	        }
647	        return found;
648	    }
649	
650	    private BigDecimal decimalOn(String key, LocalDate date, BigDecimal start) {
651	        DatedSetting d = inForce(key, date);
652	        if (d == null) return start;
653	        return d.getValue() == null ? null : new BigDecimal(d.getValue()).setScale(2);
654	    }
655	
656	    /** The clerk limit in force today; null means no limit. */
657	    public BigDecimal getClerkLimit() { return decimalOn(CLERK_LIMIT, today, null); }
658	
659	    /** The floor in force on the date: 1.00 before any is recorded. */
660	    public BigDecimal floorOn(LocalDate date) { return decimalOn(FLOOR, date, START_FLOOR); }
661	
662	    /** The cap in force today; null means none. */
663	    public BigDecimal getCap() { return decimalOn(CAP, today, null); }
664	
665	    /** The due-total, at most the cap in force today; null (n/a) stays null. */
666	    public BigDecimal capped(BigDecimal dueTotal) {
667	        BigDecimal cap = getCap();
668	        return dueTotal == null || cap == null ? dueTotal : dueTotal.min(cap);
669	    }
670	
671	    /** The sheet's terms in force on the date: 14 before any are recorded. */
672	    public int termsOn(LocalDate date) {
673	        DatedSetting d = inForce(TERMS, date);
674	        return d == null ? START_TERMS : Integer.parseInt(d.getValue());
675	    }
676	
677	    /** The grade's own terms in force on the date; null when it has none then. */
678	    public Integer gradeTermsOn(String grade, LocalDate date) {
679	        DatedSetting d = inForce(TERMS + "-" + grade, date);
680	        return d == null ? null : Integer.valueOf(d.getValue());
681	    }
682	
683	    /** The terms a claim of the grade dated on the date is given: the grade's own then, else the sheet's then. */
684	    public int termsFor(String grade, LocalDate date) {
685	        Integer own = gradeTermsOn(grade, date);
686	        return own != null ? own : termsOn(date);
687	    }
688	
689	    /** The late percent in force on the date: 0.00 before any is recorded. */
690	    public BigDecimal latePctOn(LocalDate date) { return decimalOn(LATE_PCT, date, START_LATE_PCT); }
691	
692	    public LocalDate getPolicyDate() { return policyDate; }
693	
694	    public void setPolicyDate(LocalDate policyDate) { this.policyDate = policyDate; }
695	
696	    public LocalDate getPeriodNumberingFrom() { return periodNumberingFrom; }
697	
698	    public void setPeriodNumberingFrom(LocalDate periodNumberingFrom) { this.periodNumberingFrom = periodNumberingFrom; }
699	
700	    /** Whether a claim opened now is numbered within its period rather than sheet-wide. */
701	    public boolean numbersByPeriod() {
702	        return periodNumberingFrom != null && !today.isBefore(periodNumberingFrom);
703	    }
704	
705	    /** Take the next claim number on the sheet. */
706	    public long nextClaimNumber() { return ++lastClaimNumber; }
707	}
