753	/**
754	 * Loads a sheet by id; an id never used before starts a new, empty sheet whose today is the real
755	 * date. After that the sheet's today is the only date the app uses for it ({@link #today}).
756	 */
757	@Service
758	public class SheetService {
759	
760	    private final SheetRepository sheets;
761	    private final RollupService rollup;
762	
763	    public SheetService(SheetRepository sheets, RollupService rollup) {
764	        this.sheets = sheets;
765	        this.rollup = rollup;
766	    }
767	
768	    @Transactional
769	    public Sheet load(String id, String user) {
770	        return sheets.findById(id).orElseGet(() -> {
771	            try {
772	                return sheets.saveAndFlush(new Sheet(id, user, Instant.now(), LocalDate.now()));
773	            } catch (DataIntegrityViolationException raced) {
774	                // another user started the same sheet at the same moment
775	                return sheets.findById(id).orElseThrow(() -> raced);
776	            }
777	        });
778	    }
779	
780	    /** The sheet's today: use this, never the real clock, for any date decision or default date. */
781	    @Transactional(readOnly = true)
782	    public LocalDate today(String id) {
783	        return sheets.findById(id).map(Sheet::getToday).orElseThrow(SheetNotFoundException::new);
784	    }
785	
786	    /**
787	     * Lock the sheet for numbering a claim: its sheet-wide numbers are 1, 2, ... with no gaps and never
788	     * reused, and so are its numbers within each period. The sheet stays locked until the caller's
789	     * transaction ends, so two users opening claims at once get different numbers.
790	     */
791	    @Transactional
792	    public Sheet lockForNumbering(String id) {
793	        return sheets.findForUpdate(id).orElseThrow(SheetNotFoundException::new);
794	    }
795	
796	    /** Change the sheet's today; it has no audit line of its own, only the figures it moves. */
797	    @Transactional
798	    public Sheet setToday(String id, String user, LocalDate today) {
799	        Sheet sheet = sheets.findForUpdate(id).orElseThrow(SheetNotFoundException::new);
800	        RollupService.Snapshot before = rollup.snapshot(id);
801	        sheet.setToday(today);
802	        sheets.flush();
803	        rollup.recordChanges(id, user, before);
804	        return sheet;
805	    }
806	}
