    this.quickForm.valueChanges.subscribe(() => this.quickError.set(''));
    effect(() => {
      const id = this.session.sheetId();
      this.session.loads();
      this.people.set([]);
      this.claims.set([]);
      this.selectedIds.set(new Set());
      this.bulkOpened.set(null);
